#!/usr/bin/env bash
# PreToolUse hook (Edit|Write): refuse edits to generated files.
path=$(python3 -c 'import json,sys; print(json.load(sys.stdin).get("tool_input",{}).get("file_path",""))')
if [ -f "$path" ] && head -n1 "$path" | grep -q '^# Generated by'; then
  echo "refusing to edit generated file $path: change its source and regenerate" >&2
  exit 2
fi
